var ITEM = 'glucose';
var INSTANCE_ID = 'dexcom';

var CACHE_KEY = 'ratscout.plugin.lastReading';
var LAST_ATTEMPT_KEY = 'ratscout.plugin.lastAttempt';
// Dexcom session, kept across runs (the plugin is started fresh for each request).
